import { useMutation, useQueryClient } from '@tanstack/react-query';
import axios from 'axios';
import { AutoRampUpdateParams } from '~/entities/user/model/types';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';
import { API_URLS } from '~/shared/api/api-urls';
import { queries } from '~/shared/api/query-keys';
import { resultify } from '~/shared/lib/utils/resultify';

const updateAutoRamp = (params: AutoRampUpdateParams) => {
  return resultify(axios.post<any>(API_URLS.cstmrAutoRamp, params));
};

export const useUpdateAutoRampMutation = (
  options?: MutationOptions<AutoRampUpdateParams, CBDCAxiosError, AutoRampUpdateParams>,
) => {
  const queryClient = useQueryClient();
  const { onSuccess, ...mutationOptions } = options ?? {};
  const mutation = useMutation<AutoRampUpdateParams, CBDCAxiosError, AutoRampUpdateParams>({
    ...mutationOptions,
    mutationFn: (params: AutoRampUpdateParams) => updateAutoRamp(params),
    onSuccess: async (data, variables, onMutateResult, context) => {
      await queryClient.invalidateQueries({
        queryKey: queries.cstr.cstmrWalletList.queryKey,
        refetchType: 'active',
      });

      await onSuccess?.(data, variables, onMutateResult, context);
    },
  });

  return {
    ...mutation,
  };
};
