import clsx from 'clsx';
import { isEmpty } from 'lodash-es';
import { memo, useCallback, useEffect, useState } from 'react';
import { FormProvider, useForm } from 'react-hook-form';
import { useStplatReadListQuery } from '~/entities/pin/api/use-stplat-read-list-query';
import { Term } from '~/entities/sign-up/ui/term';
import i18n from '~/shared/i18n/i18n';
import { overlay } from '~/shared/lib/overlay';
import { snackBar } from '~/shared/lib/toast';
import { BottomSheet } from '~/shared/ui/bottom-sheets/bottom-sheet';
import { CheckBox } from '~/shared/ui/check-box';
import { Dialog } from '~/shared/ui/dialogs/dialog';

type TermsInfoInputs = {
  agreed: string[];
};

type TermsInfoOption = {
  id: string;
  label: string;
  required?: boolean;
};

const options: TermsInfoOption[] = [
  {
    id: 'terms1',
    label: '자동충전 서비스 이용약관',
    required: true,
  },
  {
    id: 'terms2',
    label: '앱 이용약관 동의',
    required: true,
  },
];

const EMPTY_SELECT_ALL_VALUE = '__EMPTY_SELECT_ALL__';

export const TermsInfoBottomSheet = memo(function TermsInfoBottomSheet({
  isSheetOpen,
  onClose,
  onConfirm,
}: {
  isSheetOpen: boolean;
  onClose: () => void;
  onConfirm: () => void;
}) {
  const form = useForm<TermsInfoInputs>({ defaultValues: { agreed: [] } });
  const { getValues, register, reset, watch } = form;
  //약관 API로 변경 필요
  const { data: list } = useStplatReadListQuery();
  const allValues = list?.map((option) => option.stplatManageId);
  const [disabled, setDisabled] = useState<boolean>(false);
  const watchAllFields = watch('agreed', []);
  const selectAllValue = list && list.length > 0 ? list.map((item) => item.stplatManageId) : list ?? [];

  const handleConfirm = () => {
    const agreedValues = new Set(getValues('agreed') ?? []);
    const isAllChecked = allValues?.every((value) => agreedValues.has(value || ''));
    if (!isAllChecked) {
      snackBar(i18n.t('text:pleaseAgreeToAllTerms'));
      return;
    }
    onConfirm();
    handleClose();
  };

  const handleClose = () => {
    reset({ agreed: [] });
    onClose();
  };

  const fnTermView = useCallback(
    (index: number) => {
      if (list) {
        overlay.exclusiveOpen(({ isOpen, close, unmount }) => {
          return (
            <Dialog
              afterLeave={unmount}
              open={isOpen}
              onClose={close}
              message={<Term contents={list[index]?.stplatCn ?? ''} />}
              buttonLabel={[]}
              fullScreenMode
            />
          );
        });
      }
    },
    [list],
  );

  useEffect(() => {
    const agreedValues = new Set(getValues('agreed') ?? []);
    if (isEmpty(list)) {
      setDisabled(false);
      return;
    }

    // if (list.length === 0) {
    //   setDisabled(agreedValues.has(EMPTY_SELECT_ALL_VALUE));
    //   return;
    // }

    const hasValue = list?.map((item) => item.stplatManageId) || [];
    const isAllChecked = hasValue.every((v: any) => agreedValues.has(v)) ?? false;

    setDisabled(isAllChecked);
  }, [watchAllFields]);

  return (
    <FormProvider {...form}>
      <BottomSheet open={isSheetOpen} onClose={handleClose} title={i18n.t('termsAndConditions')}>
        <div className="policy-list">
          <ul>
            {list && list.length > 0 && (
              <li className="all">
                <CheckBox
                  label={<p className="ml10">{i18n.t('agreeToAllTerms')}</p>}
                  value={selectAllValue}
                  {...register('agreed')}
                  isSelectAll
                />
              </li>
            )}
            {list && list.length > 0 ? (
              list?.map((item, index) => (
                <li key={`${item.stplatManageId}_${index}`}>
                  <CheckBox
                    label={
                      <p>
                        <span className="req ml10">{i18n.t('required')}</span> {item.stplatNm}
                      </p>
                    }
                    value={item.stplatManageId}
                    {...register(`agreed`)}
                  />
                  <button type="button" className="btn arr-right" onClick={() => fnTermView(index)}>
                    <span>{i18n.t('viewTerms')}</span>
                  </button>
                </li>
              ))
            ) : (
              <div>등록된 약관이 없습니다.</div>
            )}
          </ul>
        </div>
        <div className="btm-btn-area confirm">
          <button type="button" className="btm-btn" onClick={handleClose}>
            {i18n.t('cancel')}
          </button>
          <button type="button" className={clsx('btm-btn app', { disabled: !disabled })} onClick={handleConfirm}>
            {i18n.t('agreeToTerms')}
          </button>
        </div>
      </BottomSheet>
    </FormProvider>
  );
});
